function solve(num) {
  if (num === 0) return 'Zero';
  const small = ['', 'One', 'Two', 'Three', 'Four', 'Five', 'Six', 'Seven',
    'Eight', 'Nine', 'Ten', 'Eleven', 'Twelve', 'Thirteen', 'Fourteen',
    'Fifteen', 'Sixteen', 'Seventeen', 'Eighteen', 'Nineteen'];
  const tens = ['', '', 'Twenty', 'Thirty', 'Forty', 'Fifty', 'Sixty',
    'Seventy', 'Eighty', 'Ninety'];
  const scales = ['', 'Thousand', 'Million', 'Billion', 'Trillion'];
  const digits = String(num).split('').map(Number);
  const n = digits.length;
  let result = '';
  let groupWord = '';
  let groupUnits = 0;
  for (let k = 0; k < n; k++) {
    const place = k;
    const d = digits[n - 1 - k];
    const inGroup = place % 3;
    const scaleIndex = Math.floor(place / 3);
    if (inGroup === 0) {
      groupUnits = d;
      groupWord = d > 0 ? small[d] : '';
    } else if (inGroup === 1) {
      if (d === 1) {
        groupWord = small[10 + groupUnits];
      } else if (d > 0) {
        groupWord = groupUnits > 0 ? tens[d] + ' ' + small[groupUnits] : tens[d];
      }
    } else if (d > 0) {
      groupWord = small[d] + ' Hundred' + (groupWord ? ' ' + groupWord : '');
    }
    if (inGroup === 2 || k === n - 1) {
      if (groupWord) {
        const tail = scaleIndex > 0 ? groupWord + ' ' + scales[scaleIndex] : groupWord;
        result = result ? tail + ' ' + result : tail;
      }
      groupWord = '';
      groupUnits = 0;
    }
  }
  return result;
}

function solve(num) {
  if (num === 0) return 'Zero';
  const small = ['', 'One', 'Two', 'Three', 'Four', 'Five', 'Six', 'Seven',
    'Eight', 'Nine', 'Ten', 'Eleven', 'Twelve', 'Thirteen', 'Fourteen',
    'Fifteen', 'Sixteen', 'Seventeen', 'Eighteen', 'Nineteen'];
  const tens = ['', '', 'Twenty', 'Thirty', 'Forty', 'Fifty', 'Sixty',
    'Seventy', 'Eighty', 'Ninety'];
  const scales = ['', 'Thousand', 'Million', 'Billion'];
  function chunkToWords(value) {
    const parts = [];
    let rest = value;
    if (rest >= 100) {
      parts.push(small[Math.floor(rest / 100)]);
      parts.push('Hundred');
      rest = rest % 100;
    }
    if (rest >= 20) {
      parts.push(tens[Math.floor(rest / 10)]);
      rest = rest % 10;
    }
    if (rest > 0) parts.push(small[rest]);
    return parts.join(' ');
  }
  const groups = [];
  let value = num;
  let index = 0;
  while (value > 0) {
    const chunk = value % 1000;
    if (chunk > 0) {
      const words = chunkToWords(chunk);
      groups.unshift(index > 0 ? words + ' ' + scales[index] : words);
    }
    value = Math.floor(value / 1000);
    index++;
  }
  return groups.join(' ');
}
